import com.tourism.business.auth.repository.UserRepository.Account;
import com.tourism.business.common.ApiException;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.transaction.annotation.Transactional;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest
@Transactional
@EnabledIfEnvironmentVariable(named="TEST_DB_URL",matches=".+")
class OrganizationTest {
    @DynamicPropertySource static void database(DynamicPropertyRegistry p)throws Exception{PublicReservationTest.database(p);}
    @Autowired JdbcTemplate jdbc;@Autowired CalendarService calendar;@Autowired ActivityService activity;@Autowired tools.jackson.databind.ObjectMapper mapper;
    @Autowired org.springframework.web.context.WebApplicationContext context;@Autowired org.springframework.security.web.FilterChainProxy security;
    long actor,other;String trace;
    String key(){return UUID.randomUUID().toString();}
    @BeforeEach void setup(){jdbc.update("INSERT dbo.AppUser(username,passwordHash,name,email,phone,role) VALUES('organization.test','unused','Task Staff','private@example.invalid','00000000','STAFF'),('organization.other','unused','Other Staff','other@example.invalid','00000000','STAFF')");actor=jdbc.queryForObject("SELECT id FROM dbo.AppUser WHERE username='organization.test'",Long.class);other=jdbc.queryForObject("SELECT id FROM dbo.AppUser WHERE username='organization.other'",Long.class);trace=key();jdbc.update("EXEC sys.sp_set_session_context @key=N'actorId',@value=?",actor);jdbc.update("EXEC sys.sp_set_session_context @key=N'requestId',@value=?",trace);}
    @AfterEach void clear(){jdbc.execute("EXEC sys.sp_set_session_context @key=N'actorId',@value=NULL; EXEC sys.sp_set_session_context @key=N'requestId',@value=NULL;");}
    Save request(LocalDate date,String status,String version){return new Save(date,"Private title","Private description",status,version);}
    Map<?,?> day(String month,String date){return ((List<Map<?,?>>)calendar.month(month).get("days")).stream().filter(x->date.equals(x.get("date"))).findFirst().orElseThrow();}
    @Test void pa21CalendarAcrossYearsCompletionMoveAndDelete(){LocalDate date=LocalDate.of(2084,12,31);String key=key();var request=request(date,"PENDING",null);var created=calendar.save(null,request,key,actor);long id=Long.parseLong(created.get("id").toString());assertEquals(created,calendar.save(null,request,key,actor));assertEquals(1L,day("2084-12",date.toString()).get("pendingTasks"));assertEquals(29,((List<?>)calendar.month("2084-02").get("days")).size());var completed=calendar.save(id,request(date,"COMPLETED",created.get("version").toString()),key(),other);assertEquals(Long.toString(actor),completed.get("authorId"));assertEquals(Long.toString(other),completed.get("updatedBy"));assertEquals(1L,day("2084-12",date.toString()).get("tasks"));assertEquals(0L,day("2084-12",date.toString()).get("pendingTasks"));assertEquals("VERSION_CONFLICT",assertThrows(ApiException.class,()->calendar.save(id,request(date,"PENDING",created.get("version").toString()),key(),actor)).code);var moved=calendar.save(id,request(date.plusDays(1),"COMPLETED",completed.get("version").toString()),key(),other);assertEquals(0L,calendar.tasks(date,0,20).get("total"));assertEquals(1L,calendar.tasks(date.plusDays(1),0,20).get("total"));String deleteKey=key();var deletion=new Delete(moved.get("version").toString());var deleted=calendar.delete(id,deletion,deleteKey,other);assertEquals(deleted,calendar.delete(id,deletion,deleteKey,other));assertEquals("NOT_FOUND",assertThrows(ApiException.class,()->calendar.detail(id)).code);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM dbo.AuditLog WHERE entity='Task' AND entityId=? AND operation='DELETE'",Integer.class,id));}
    @Test void pa16TaskAuditAndPa17GroupedFilteredPrivateTimeline(){LocalDate date=LocalDate.now(ZoneId.of("America/Costa_Rica"));for(int i=0;i<3;i++)calendar.save(null,request(date,"PENDING",null),key(),actor);jdbc.update("UPDATE dbo.Task SET status='COMPLETED' WHERE authorId=?",actor);assertEquals(3,jdbc.queryForObject("SELECT COUNT(*) FROM dbo.AuditLog WHERE requestId=? AND entity='Task' AND operation='UPDATE'",Integer.class,trace));jdbc.update("INSERT dbo.ActivityEvent(eventType,actorId,requestId,outcome) VALUES('LOGIN',?,?,'FAILURE')",actor,trace);var group=activity.list(date,date,actor,"","",0,1);assertEquals(1L,group.get("total"));var item=(Map<?,?>)((List<?>)group.get("items")).getFirst();assertEquals(trace,item.get("groupKey"));assertTrue(((Number)item.get("entryCount")).longValue()>=4);var entries=activity.entries(trace,0,2);assertEquals(2,((List<?>)entries.get("items")).size());assertFalse(((List<?>)activity.entries(trace,1,2).get("items")).isEmpty());assertEquals(0L,activity.list(date,date,other,"","Task",0,20).get("total"));assertEquals(1L,activity.list(date,date,actor,"LOGIN","",0,20).get("total"));String json=mapper.writeValueAsString(entries);for(String secret:List.of("Private title","Private description","private@example.invalid","unused","passwordHash","beforeData","afterData"))assertFalse(json.contains(secret));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM dbo.AuditLog WHERE requestId=? AND (beforeData LIKE '%Private%' OR afterData LIKE '%Private%')",Integer.class,trace));assertThrows(ApiException.class,()->activity.list(date,date.minusDays(1),null,"","",0,20));assertThrows(ApiException.class,()->activity.entries(trace,0,101));jdbc.update("DELETE dbo.Task WHERE authorId=?",actor);assertEquals(3,jdbc.queryForObject("SELECT COUNT(*) FROM dbo.AuditLog WHERE requestId=? AND entity='Task' AND operation='DELETE'",Integer.class,trace));}
    @Test void markersOnlyCountConfirmedAndDatesUseCostaRica(){LocalDate date=LocalDate.of(2085,1,2);jdbc.update("INSERT dbo.VisitDay(visitDate) VALUES(?)",date);long day=jdbc.queryForObject("SELECT id FROM dbo.VisitDay WHERE visitDate=?",Long.class,date);jdbc.update("INSERT dbo.RatePlan(adultPrice,childPrice,seniorPrice,parkingPrice,effectiveAt) VALUES(0,0,0,0,SYSUTCDATETIME())");long rate=jdbc.queryForObject("SELECT MAX(id) FROM dbo.RatePlan",Long.class);for(String status:List.of("CONFIRMED","CANCELLED","CHECKED_IN"))jdbc.update("INSERT dbo.Reservation(code,visitDayId,ratePlanId,name,email,phone,adults,children,seniors,vehicles,adultPrice,childPrice,seniorPrice,parkingPrice,total,status) VALUES(?,?,?,'Private visitor','hidden@example.invalid','00000000',1,0,0,0,0,0,0,0,0,?)",key(),day,rate,status);assertEquals(1L,day("2085-01",date.toString()).get("reservations"));jdbc.update("INSERT dbo.ActivityEvent(eventType,actorId,outcome,occurredAt) VALUES('BOUNDARY',?,'TEST','2085-01-02T05:59:59'),('BOUNDARY',?,'TEST','2085-01-02T06:00:00')",actor,actor);assertEquals(1L,activity.list(date,date,actor,"BOUNDARY","",0,20).get("total"));assertEquals(1L,activity.list(date.minusDays(1),date.minusDays(1),actor,"BOUNDARY","",0,20).get("total"));assertThrows(ApiException.class,()->calendar.month("0000-01"));assertThrows(ApiException.class,()->calendar.save(null,new Save(date," ","valid","PENDING",null),key(),actor));}
    @Test void staffCanManageTasksButCannotReadOrChangeActivity()throws Exception{var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup(context).addFilters(security).build();var account=new Account(actor,"organization.test","unused","Task Staff","STAFF",true);var ctx=org.springframework.security.core.context.SecurityContextHolder.createEmptyContext();ctx.setAuthentication(org.springframework.security.authentication.UsernamePasswordAuthenticationToken.authenticated(account,null,account.getAuthorities()));var session=new org.springframework.mock.web.MockHttpSession();session.setAttribute("SPRING_SECURITY_CONTEXT",ctx);session.setAttribute("authenticatedAt",System.currentTimeMillis());var csrf=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/auth/csrf").session(session)).andReturn();String token=mapper.readTree(csrf.getResponse().getContentAsString()).get("token").asText();var body=mapper.writeValueAsString(request(LocalDate.of(2086,1,1),"PENDING",null));assertEquals(403,mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/tasks").session(session).contentType("application/json").content(body)).andReturn().getResponse().getStatus());assertEquals(201,mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/tasks").session(session).header("X-CSRF-TOKEN",token).header("Idempotency-Key",key()).contentType("application/json").content(body)).andReturn().getResponse().getStatus());for(String path:List.of("/activity?from=2086-01-01&to=2086-01-01","/activity/options","/activity/A-1/entries"))assertEquals(403,mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1"+path).session(session)).andReturn().getResponse().getStatus());assertEquals(200,mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/calendar?month=2086-01").session(session)).andReturn().getResponse().getStatus());assertEquals(401,mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/tasks?date=2086-01-01")).andReturn().getResponse().getStatus());jdbc.update("UPDATE dbo.AppUser SET role='ADMIN' WHERE id=?",actor);var admin=new Account(actor,"organization.test","unused","Task Staff","ADMIN",true);ctx.setAuthentication(org.springframework.security.authentication.UsernamePasswordAuthenticationToken.authenticated(admin,null,admin.getAuthorities()));var options=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/activity/options").session(session)).andReturn();assertEquals(200,options.getResponse().getStatus(),options.getResponse().getContentAsString());assertFalse(options.getResponse().getContentAsString().contains("private@example.invalid"));assertEquals(200,mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/activity?from=2020-01-01&to=2090-01-01").session(session)).andReturn().getResponse().getStatus());assertEquals(405,mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/activity").session(session).header("X-CSRF-TOKEN",token).contentType("application/json").content("{}")).andReturn().getResponse().getStatus());}
}
